export function layout(width,height){const stacked=width<650,short=height<300,compact=stacked&&height<500;return {width,height,stacked,short,x:stacked?width*.12:width*.07,w:stacked?width*.76:width*.43,y:compact?height*.44:stacked?Math.max(200,height*.38):(short?165:height*.57),k:compact?.75:short?.7:1,ix:stacked?width*.1:width*.58,iy:compact?height-176:stacked?Math.max(290,height*.58):(short?70:height*.28),iw:stacked?width*.8:width*.36};}
